package main

import (
	"MedicalQuestionnaireService/libs"
	"MedicalQuestionnaireService/middleware"
	"MedicalQuestionnaireService/models"

	"MedicalQuestionnaireService/web_server"
	"flag"
	"fmt"
	"log"
	// "github.com/iris-contrib/swagger/v12"
	// "github.com/iris-contrib/swagger/v12/swaggerFiles"
	// _ "./docs" // docs is generated by Swag CLI, you have to import it.
)

// swagger middleware for Iris
// swagger embed files

// @title Swagger Example API
// @version 1.0
// @description This is a sample server Petstore server.
// @termsOfService http://swagger.io/terms/

// @contact.name API Support
// @contact.url http://www.swagger.io/support
// @contact.email support@swagger.io

// @license.name Apache 2.0
// @license.url http://www.apache.org/licenses/LICENSE-2.0.html

// @host 0.0.0.0:8085
// @BasePath /vue

var ConfigPath = flag.String("c", "", "ConfigPath")
var SyncPerms = flag.Bool("p", true, "同期許可")
var Model string

func main() {
	middleware.InitCron()

	libs.InitConfig(*ConfigPath, Model)
	libs.InitDb()
	models.Seed()
	irisServer := web_server.NewServer(nil)
	if irisServer == nil {
		panic("Http 初期化失敗")
	} else {
		log.Println("Http 初期化成功")
	}
	irisServer.NewApp()

	if *SyncPerms {
		fmt.Println("同期許可：")
		fmt.Println()
		// access_perm.AddPerm()
	}

	err := irisServer.Serve()
	if err != nil {
		panic(err)
	}
}
